def squash(s: str) -> str:
    if not s:
        return ""

    def esc(c: str) -> str:
        if c.isdigit() or c == "\\":
            return "\\" + c
        return c

    result = []
    n = len(s)
    i = 0

    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        run_len = j - i
        c_esc = esc(s[i])

        if run_len >= 3:
            result.append(str(run_len))
            result.append(c_esc)
        else:
            result.append(c_esc * run_len)

        i = j

    return "".join(result)
